/*
 * FC: #123 One inscription abbreviation. The key is qualified by the table
 * it came from: "St" is the strength bonus in flag_insc_plus but the stun
 * brand in flag_insc_brand, and "Lv" is levitation in flag_insc_misc but
 * slay-living in flag_insc_kill. A bare code cannot be looked up.
 *
 * They live in the `F:` table, which exists for exactly this reason -- keys
 * that are bare words and would collide in the general catalogue.
 */
static cptr _insc_abbrev(cptr tag, cptr code)
{
    char key[64];
    cptr ja;

    if (!fc_lang_enabled()) return code;
    if (strlen(tag) + strlen(code) + 8 >= sizeof(key)) return code;
    sprintf(key, "insc.%s.%s", tag, code);
    ja = fc_frame_label(key);
    /* fc_frame_label() hands the key straight back when it is not in the
     * table, and that key is this stack buffer -- never return it. */
    return (ja == key) ? code : ja;
}

